#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m13-trace-a-packet pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m13-trace-a-packet
CHECKS="pods-ready pod-a-ip pod-b-ip pod-b-node pod-b-node-address pod-b-cidr source-seen-by-pod-b veth-of-pod-a hop-count"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m13-trace-a-packet
checks:
  - id: pods-ready
    describe: Pods net-a and net-b are both ready
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/part-of=shelf
      - -o
      - jsonpath={.items[*].status.containerStatuses[*].ready}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: true true
    hint: Run `kubectl get pods --namespace shelf --output wide`. The setup pulls the busybox image from Docker Hub once, so the first start can take a minute. If a Pod stays Pending, read `kubectl describe pod` and look at the events.
  - id: pod-a-ip
    describe: The answer file gives net-a's IP address
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - pod
        - net-a
        - -n
        - shelf
        - -o
        - json
      jsonpath: "{.status.podIP}"
    expect:
      jsonpath: "{.pod-a.ip}"
      matches: (?i)^\s*${derived}\s*$
    hint: Read the IP column of `kubectl get pods --namespace shelf --output wide`, or run `kubectl get pod net-a --namespace shelf --output jsonpath='{.status.podIP}'`.
  - id: pod-b-ip
    describe: The answer file gives net-b's IP address
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - pod
        - net-b
        - -n
        - shelf
        - -o
        - json
      jsonpath: "{.status.podIP}"
    expect:
      jsonpath: "{.pod-b.ip}"
      matches: (?i)^\s*${derived}\s*$
    hint: Read the IP column of `kubectl get pods --namespace shelf --output wide` for net-b.
  - id: pod-b-node
    describe: The answer file names the node that runs net-b
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - pod
        - net-b
        - -n
        - shelf
        - -o
        - json
      jsonpath: "{.spec.nodeName}"
    expect:
      jsonpath: "{.pod-b.node}"
      matches: (?i)^\s*${derived}\s*$
    hint: Read the NODE column of `kubectl get pods --namespace shelf --output wide` for net-b.
  - id: pod-b-node-address
    describe: The answer file gives that node's address on the node network
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - node
        - reconcile-control-plane
        - -o
        - json
      jsonpath: '{.status.addresses[?(@.type=="InternalIP")].address}'
    expect:
      jsonpath: "{.pod-b.node-address}"
      matches: (?i)^\s*${derived}\s*$
    hint: "`kubectl get node reconcile-control-plane --output wide` shows the node's INTERNAL-IP. It is the address in the second hop of traceroute."
  - id: pod-b-cidr
    describe: The answer file gives that node's Pod CIDR
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - node
        - reconcile-control-plane
        - -o
        - json
      jsonpath: "{.spec.podCIDR}"
    expect:
      jsonpath: "{.pod-b.pod-cidr}"
      matches: (?i)^\s*${derived}\s*$
    hint: "`kubectl get node reconcile-control-plane --output jsonpath='{.spec.podCIDR}'` prints it. net-b's address is inside this range."
  - id: source-seen-by-pod-b
    describe: The address that net-b's server sees is net-a's own IP address (no NAT)
    file: trace-a-packet/answers.yaml
    derive:
      kubectl:
        - get
        - pod
        - net-a
        - -n
        - shelf
        - -o
        - json
      jsonpath: "{.status.podIP}"
    expect:
      jsonpath: "{.request.source-seen-by-pod-b}"
      matches: (?i)^\s*${derived}\s*$
    hint: From net-a, run `wget -qO- http://<net-b's IP>:8080/cgi-bin/whoami` with `kubectl exec net-a --namespace shelf --`. The page prints the address that the connection came from. It is net-a's address, because Pod-to-Pod traffic is not translated.
  - id: veth-of-pod-a
    describe: The answer file names a veth in the form that the CNI gives it
    file: trace-a-packet/answers.yaml
    expect:
      jsonpath: "{.path.veth-of-pod-a}"
      matches: ^veth[0-9a-f]{8}$
    hint: "Read the node's routes: `docker exec reconcile-worker ip route`. The line for net-a's address ends with `dev veth` and eight more characters. Copy that name."
  - id: hop-count
    describe: The answer file says traceroute shows 3 hops to net-b
    file: trace-a-packet/answers.yaml
    expect:
      jsonpath: "{.path.hops}"
      matches: ^\s*3\s*$
    hint: "Run `kubectl exec net-a --namespace shelf -- traceroute -n <net-b's IP>`. The Pods are on different nodes: the first hop is the node's end of net-a's veth, the second is the other node, the third is net-b."
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
